package dev.trentdb.storage;import dev.trentdb.storage.format.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DuckDbPrimitiveColumnMetadataReaderTest{@TempDir Path d;@Test void readsIntegerDescriptorBeforePayloadDecompression(){try(var m=file("golden",outer(segment(2,1)))){var x=new DuckDbPrimitiveColumnMetadataReader(m,new DuckDbTableEntryEnvelope.MetaPointer(0,0),DuckDbTableCreateInfo.ScalarLogicalType.INTEGER).read();assertEquals(1,x.dataSegments().size());assertEquals(2,x.dataSegments().get(0).tupleCount());assertEquals(1,x.dataSegments().get(0).compressionType());assertEquals(OptionalLong.of(2),x.dataSegments().get(0).statistics().min());assertEquals(OptionalLong.of(9),x.dataSegments().get(0).statistics().max());assertEquals(List.of(),x.validitySegments());assertEquals(DuckDbPrimitiveColumnMetadata.Boundary.BLOCK_PAYLOAD_DECOMPRESSION_UNSUPPORTED,x.boundary());}}@Test void rejectsCompressionBeforePayloadDecoding(){var b=new ByteArrayOutputStream();f(b,101);u(b,1);f(b,102);f(b,100);u(b,0);end(b);f(b,103);u(b,2);try(var m=file("compression",outer(b.toByteArray()))){var e=assertThrows(StorageFormatException.class,()->new DuckDbPrimitiveColumnMetadataReader(m,new DuckDbTableEntryEnvelope.MetaPointer(0,0),DuckDbTableCreateInfo.ScalarLogicalType.INTEGER).read());assertEquals("DuckDB primitive segment compression is unsupported: 2",e.getMessage());}}private byte[] outer(byte[] s){var b=new ByteArrayOutputStream();f(b,100);u(b,1);b.writeBytes(s);f(b,101);end(b);end(b);return b.toByteArray();}private byte[] segment(int n,int c){var b=new ByteArrayOutputStream();f(b,101);u(b,n);f(b,102);f(b,100);u(b,0);f(b,101);u(b,8);end(b);f(b,103);u(b,c);f(b,104);f(b,100);b.write(0);f(b,101);b.write(1);f(b,102);u(b,2);f(b,103);bound(b,200,2);bound(b,201,9);end(b);end(b);end(b);return b.toByteArray();}private void bound(ByteArrayOutputStream b,int id,int v){f(b,id);f(b,100);b.write(1);f(b,101);u(b,v);end(b);}private SingleFileBlockManager file(String n,byte[]p){var x=d.resolve(n);try(var w=SingleFileBlockManager.create(x,new byte[16])){var b=new byte[w.usableBlockSize()];for(int i=0;i<8;i++)b[i]=(byte)(-1L>>>8*i);System.arraycopy(p,0,b,8,p.length);w.writeBlock(0,b);}return SingleFileBlockManager.openMetadataReadOnly(x);}private static void f(ByteArrayOutputStream b,int x){b.write(x);b.write(x>>>8);}private static void end(ByteArrayOutputStream b){f(b,65535);}private static void u(ByteArrayOutputStream b,long x){do{int n=(int)(x&127);x>>>=7;b.write(x==0?n:n|128);}while(x!=0);}}
